package edu.synergy.algorithms.trees;
public final class BinarySearchTree { public static final class Node{public int value;public Node left,right;Node(int v){value=v;}} private Node root; public Node root(){return root;} public void insert(int value){root=insert(root,value);} private Node insert(Node n,int v){if(n==null)return new Node(v);if(v<n.value)n.left=insert(n.left,v);else if(v>n.value)n.right=insert(n.right,v);return n;} public Node search(int v){Node n=root;while(n!=null){if(v==n.value)return n;n=v<n.value?n.left:n.right;}return null;} public void delete(int v){root=delete(root,v);} private Node delete(Node n,int v){if(n==null)return null;if(v<n.value)n.left=delete(n.left,v);else if(v>n.value)n.right=delete(n.right,v);else{if(n.left==null)return n.right;if(n.right==null)return n.left;Node successor=min(n.right);n.value=successor.value;n.right=delete(n.right,successor.value);}return n;} private Node min(Node n){while(n.left!=null)n=n.left;return n;} }
